-- ============================================================
-- V15: Alerts (C4) and session checkpoints (C5).
--
-- C4: alerts are generated by Control from ingested high-risk audit events
--     (risk_score >= threshold). Each alert links to a trace_id, which the
--     Decision BOM (A6) uses to reconstruct the full trajectory, judgement
--     basis and disposal — the "single alert → full traceability" flow.
-- C5: per-session checkpoints maintained from trace ingest, so session context
--     survives a Redis eviction and stays queryable for interruption/resume
--     evidence.
-- ============================================================

CREATE TABLE tb_alert (
    alert_id       VARCHAR(64)  PRIMARY KEY,
    tenant_id      VARCHAR(64)  NOT NULL,
    trace_id       VARCHAR(128),
    session_id     VARCHAR(128),
    scene          VARCHAR(64),
    rule_id        VARCHAR(128),
    reason_code    VARCHAR(64),
    risk_score     INTEGER      NOT NULL DEFAULT 0,
    effective_action VARCHAR(16),
    status         VARCHAR(16)  NOT NULL DEFAULT 'open',   -- open|acked|closed
    created_at     TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    acked_by       VARCHAR(128),
    acked_at       TIMESTAMP    NULL
);
CREATE INDEX idx_tb_alert_tenant ON tb_alert (tenant_id, status, created_at);

CREATE TABLE tb_session_checkpoint (
    tenant_id        VARCHAR(64)  NOT NULL,
    session_id       VARCHAR(128) NOT NULL,
    last_chain_seq   BIGINT       NOT NULL DEFAULT 0,
    last_occurred_at TIMESTAMP    NULL,
    event_count      BIGINT       NOT NULL DEFAULT 0,
    tool_names       VARCHAR(512),
    saved_at         TIMESTAMP    NOT NULL DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (tenant_id, session_id)
);
